compile.workshop:
variables {
    global:
        0: g
        1: h
}

rule ("x") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(g, 0, 3, 1);
            Skip If(Compare(Global.h, ==, 3), 3);
            Set Global Variable(h, 1);
            Wait(1, Ignore Condition);
        End;
        //lbl_done:
        Set Global Variable(h, 9);
    }
}

